// File output shared by both entry points. Each output directory is owned by
// the generator: files it no longer produces are removed.

import { mkdirSync, readdirSync, rmdirSync, unlinkSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';

export const GENERATED_NOTICE = [
  'Generated by packages/ui/scripts/tokens from packages/ui/tokens (ADR 0026).',
  'Do not edit by hand: change scripts/tokens/inputs.mjs and run `make tokens-gen`.'
];

function listFiles(dir) {
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return [];
  }
  return entries.flatMap((entry) => {
    const path = join(dir, entry.name);
    return entry.isDirectory() ? listFiles(path) : [path];
  });
}

function removeEmptyDirs(dir, root) {
  for (const entry of readdirSync(dir, { withFileTypes: true })) {
    if (entry.isDirectory()) removeEmptyDirs(join(dir, entry.name), root);
  }
  if (dir !== root && readdirSync(dir).length === 0) rmdirSync(dir);
}

/** Writes `files` (relative path → contents) into `dir` and removes the rest. */
export function writeOwnedDir(dir, files) {
  const keep = new Set(Object.keys(files));
  for (const path of listFiles(dir)) {
    if (!keep.has(relative(dir, path))) unlinkSync(path);
  }
  for (const [file, contents] of Object.entries(files)) {
    const path = join(dir, file);
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, contents);
  }
  removeEmptyDirs(dir, dir);
}

/** Formats a JSON-ready object the way Prettier leaves it. */
export const json = (data) => `${JSON.stringify(data, null, 2)}\n`;
